      sources: [{ name: "I Can Fix Him (No Really I Can) — Wikipedia", url: "https://en.wikipedia.org/wiki/I_Can_Fix_Him_(No_Really_I_Can)" }, { name: "The Tortured Poets Department — Wikipedia", url: "https://en.wikipedia.org/wiki/The_Tortured_Poets_Department" }, { name: "I Can Fix Him (No Really I Can) — Official Charts", url: "https://www.officialcharts.com/songs/taylor-swift-i-can-fix-him-no-really-i-can/" }, { name: "Taylor Swift Charts 32 Songs on Hot 100, Including Every 'Tortured Poets' Track", url: "https://www.billboard.com/music/chart-beat/taylor-swift-32-songs-hot-100-one-week-tortured-poets-department-1235669025/" }],
